import { useQuery } from "@tanstack/react-query";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Cpu, Circle, CircleAlert, Plus, Battery, Signal } from "lucide-react";
import type { Device } from "@shared/schema";

export default function DeviceManagementPanel() {
  const { data: devices = [] } = useQuery<Device[]>({
    queryKey: ["/api/devices"],
    refetchInterval: 5000,
  });

  const getStatusIcon = (status: string) => {
    switch (status) {
      case "online": return <Circle className="w-3 h-3 text-accent fill-current" />;
      case "warning": return <CircleAlert className="w-3 h-3 text-yellow-400 fill-current" />;
      case "error": return <CircleAlert className="w-3 h-3 text-destructive fill-current" />;
      default: return <Circle className="w-3 h-3 text-muted-foreground fill-current" />;
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case "online": return "text-accent";
      case "warning": return "text-yellow-400";
      case "error": return "text-destructive";
      default: return "text-muted-foreground";
    }
  };

  const getStatusBg = (status: string) => {
    switch (status) {
      case "online": return "bg-accent/20";
      case "warning": return "bg-yellow-400/20";
      case "error": return "bg-destructive/20";
      default: return "bg-muted/20";
    }
  };

  const getDeviceIconColor = (status: string) => {
    switch (status) {
      case "online": return "text-accent bg-accent/20";
      case "warning": return "text-yellow-400 bg-yellow-400/20";
      case "error": return "text-destructive bg-destructive/20";
      default: return "text-muted-foreground bg-muted/20";
    }
  };

  const formatUptime = (seconds: number) => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    return `${hours}h ${minutes}m`;
  };

  const formatTimeAgo = (date: Date) => {
    const seconds = Math.floor((new Date().getTime() - new Date(date).getTime()) / 1000);
    if (seconds < 60) return `${seconds} seconds ago`;
    const minutes = Math.floor(seconds / 60);
    if (minutes < 60) return `${minutes} minutes ago`;
    const hours = Math.floor(minutes / 60);
    return `${hours} hours ago`;
  };

  const getSignalBars = (strength: number) => {
    const bars = [];
    const level = Math.abs(strength);
    for (let i = 0; i < 4; i++) {
      const isActive = level < 50 + (i * 15); // -50 to -95 dBm range
      bars.push(
        <div
          key={i}
          className={`w-1 ${isActive ? 'bg-accent' : 'bg-muted/40'} rounded-sm`}
          style={{ height: `${8 + i * 2}px` }}
        />
      );
    }
    return bars;
  };

  return (
    <div data-testid="panel-device-management">
      <h2 className="text-xl font-semibold mb-6 flex items-center">
        <Cpu className="w-5 h-5 text-primary mr-3" />
        ESP32 Device Management
      </h2>

      <div className="space-y-4">
        {devices.map((device) => (
          <Card key={device.id} className="glass-card" data-testid={`device-${device.id}`}>
            <CardContent className="p-6">
              <div className="flex items-center justify-between mb-4">
                <div className="flex items-center space-x-3">
                  <div className={`w-10 h-10 rounded-lg flex items-center justify-center ${getDeviceIconColor(device.status)}`}>
                    <Cpu className="w-5 h-5" />
                  </div>
                  <div>
                    <h3 className="font-medium text-foreground" data-testid={`text-device-name-${device.id}`}>
                      {device.name}
                    </h3>
                    <p className="text-sm text-muted-foreground">MAC: {device.macAddress}</p>
                  </div>
                </div>
                <div className={`px-3 py-1 text-sm rounded-full flex items-center space-x-1 ${getStatusBg(device.status)} ${getStatusColor(device.status)}`}>
                  {getStatusIcon(device.status)}
                  <span className="capitalize">{device.status}</span>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <span className="text-sm text-muted-foreground">Battery</span>
                  <div className="flex items-center space-x-2 mt-1">
                    <Battery className="w-4 h-4 text-muted-foreground" />
                    <div className="flex-1 bg-muted/20 rounded-full h-2">
                      <div 
                        className={`h-2 rounded-full transition-all duration-500 ${
                          (device.batteryLevel || 0) > 50 ? 'bg-accent' : 
                          (device.batteryLevel || 0) > 20 ? 'bg-yellow-400' : 'bg-destructive'
                        }`}
                        style={{ width: `${device.batteryLevel || 0}%` }}
                      />
                    </div>
                    <span className="text-sm text-foreground" data-testid={`text-battery-${device.id}`}>
                      {device.batteryLevel || 0}%
                    </span>
                  </div>
                </div>
                <div>
                  <span className="text-sm text-muted-foreground">Signal</span>
                  <div className="flex items-center space-x-2 mt-1">
                    <Signal className="w-4 h-4 text-muted-foreground" />
                    <div className="flex items-end space-x-1">
                      {getSignalBars(device.signalStrength || 0)}
                    </div>
                    <span className="text-sm text-foreground ml-2" data-testid={`text-signal-${device.id}`}>
                      {device.signalStrength || 0} dBm
                    </span>
                  </div>
                </div>
                <div>
                  <span className="text-sm text-muted-foreground">Uptime</span>
                  <p className="text-sm text-foreground mt-1" data-testid={`text-uptime-${device.id}`}>
                    {formatUptime(device.uptime || 0)}
                  </p>
                </div>
                <div>
                  <span className="text-sm text-muted-foreground">Packets</span>
                  <p className="text-sm text-foreground mt-1" data-testid={`text-packets-${device.id}`}>
                    {(device.packetsSent || 0).toLocaleString()} sent
                  </p>
                </div>
              </div>

              <div className="flex items-center justify-between mt-4 pt-4 border-t border-border">
                <span className="text-sm text-muted-foreground">Last Activity</span>
                <span 
                  className={`text-sm ${device.status === 'warning' ? 'text-yellow-400' : 'text-foreground'}`}
                  data-testid={`text-last-activity-${device.id}`}
                >
                  {formatTimeAgo(device.lastActivity!)}
                </span>
              </div>
            </CardContent>
          </Card>
        ))}

        {/* Add Device Button */}
        <Button 
          variant="ghost"
          className="w-full glass-card border-2 border-dashed border-border hover:border-primary/50 hover:bg-primary/5 transition-colors group p-6 h-auto"
          data-testid="button-add-device"
        >
          <div className="flex items-center justify-center space-x-3">
            <div className="w-10 h-10 bg-primary/20 rounded-lg flex items-center justify-center group-hover:bg-primary/30 transition-colors">
              <Plus className="w-5 h-5 text-primary" />
            </div>
            <span className="text-muted-foreground group-hover:text-foreground">Add New Device</span>
          </div>
        </Button>
      </div>
    </div>
  );
}

client/src/components/health-charts-pane.content:
import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Area, AreaChart } from "recharts";
import { TrendingUp, AlertTriangle } from "lucide-react";
import type { Device, HealthMetrics } from "@shared/schema";

export default function HealthChartsPanel() {
  const [selectedDevice, setSelectedDevice] = useState<string>("");
  const [timeRange, setTimeRange] = useState("24");
  const [activeMetric, setActiveMetric] = useState<"heartRate" | "spO2" | "stepCount">("heartRate");

  const { data: devices = [] } = useQuery<Device[]>({
    queryKey: ["/api/devices"],
  });

  const { data: historyData = [] } = useQuery<HealthMetrics[]>({
    queryKey: ["/api/health-metrics/history", selectedDevice || devices[0]?.id, timeRange],
    enabled: !!(selectedDevice || devices[0]?.id),
    refetchInterval: 30000,
  });

  // Transform data for charts
  const chartData = historyData.map((metric, index) => ({
    time: new Date(metric.timestamp || 0).toLocaleTimeString('en-US', { 
      hour: '2-digit', 
      minute: '2-digit' 
    }),
    heartRate: metric.heartRate || 0,
    spO2: metric.spO2 || 0,
    stepCount: metric.stepCount || 0,
    index,
  }));

  // Calculate statistics
  const currentValue = chartData.length > 0 ? chartData[chartData.length - 1][activeMetric] : 0;
  const avgValue = chartData.length > 0 
    ? Math.round(chartData.reduce((sum, d) => sum + d[activeMetric], 0) / chartData.length)
    : 0;
  const maxValue = chartData.length > 0 
    ? Math.max(...chartData.map(d => d[activeMetric]))
    : 0;
  const minValue = chartData.length > 0 
    ? Math.min(...chartData.map(d => d[activeMetric]))
    : 0;

  // Detect anomalies (simple threshold-based)
  const getAnomalies = () => {
    if (activeMetric === "heartRate") {
      return chartData.filter(d => d.heartRate > 100 || d.heartRate < 60);
    } else if (activeMetric === "spO2") {
      return chartData.filter(d => d.spO2 < 95);
    }
    return [];
  };

  const anomalies = getAnomalies();
  const latestAnomaly = anomalies.length > 0 ? anomalies[anomalies.length - 1] : null;

  const getMetricColor = (metric: string) => {
    switch (metric) {
      case "heartRate": return "hsl(0, 84%, 60%)"; // Red
      case "spO2": return "hsl(217, 91%, 60%)"; // Blue
      case "stepCount": return "hsl(145, 63%, 49%)"; // Green
      default: return "hsl(191, 100%, 50%)"; // Primary
    }
  };

  const getMetricLabel = (metric: string) => {
    switch (metric) {
      case "heartRate": return "BPM";
      case "spO2": return "SpO₂ %";
      case "stepCount": return "IR";
      default: return "";
    }
  };

  return (
    <div data-testid="panel-health-charts">
      <h2 className="text-xl font-semibold mb-6 flex items-center">
        <TrendingUp className="w-5 h-5 text-primary mr-3" />
        Health Data Analysis
      </h2>

      <Card className="glass-card">
        <CardContent className="pt-6">
          {/* Chart Controls */}
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center space-x-4">
              <Select value={timeRange} onValueChange={setTimeRange}>
                <SelectTrigger className="w-40" data-testid="select-time-range">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="1">Last Hour</SelectItem>
                  <SelectItem value="6">Last 6 Hours</SelectItem>
                  <SelectItem value="24">Last 24 Hours</SelectItem>
                  <SelectItem value="168">Last 7 Days</SelectItem>
                </SelectContent>
              </Select>

              {devices.length > 1 && (
                <Select value={selectedDevice} onValueChange={setSelectedDevice}>
                  <SelectTrigger className="w-40" data-testid="select-device">
                    <SelectValue placeholder="All Devices" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Devices</SelectItem>
                    {devices.map(device => (
                      <SelectItem key={device.id} value={device.id}>
                        {device.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}

              <div className="flex items-center space-x-2">
                <Button
                  variant={activeMetric === "heartRate" ? "default" : "ghost"}
                  size="sm"
                  onClick={() => setActiveMetric("heartRate")}
                  data-testid="button-heart-rate"
                >
                  Heart Rate
                </Button>
                <Button
                  variant={activeMetric === "spO2" ? "default" : "ghost"}
                  size="sm"
                  onClick={() => setActiveMetric("spO2")}
                  data-testid="button-spo2"
                >
                  SpO₂
                </Button>
                <Button
                  variant={activeMetric === "stepCount" ? "default" : "ghost"}
                  size="sm"
                  onClick={() => setActiveMetric("stepCount")}
                  data-testid="button-IR"
                >
                  IR
                </Button>
              </div>
            </div>

            {latestAnomaly && (
              <div className="flex items-center space-x-2" data-testid="alert-anomaly">
                <AlertTriangle className="w-4 h-4 text-destructive" />
                <span className="text-sm text-muted-foreground">
                  Anomaly detected at {latestAnomaly.time}
                </span>
              </div>
            )}
          </div>

          {/* Chart Area */}
          <div className="h-80 w-full" data-testid="chart-health-data">
            {chartData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={chartData}>
                  <defs>
                    <linearGradient id="areaGradient" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor={getMetricColor(activeMetric)} stopOpacity={0.3}/>
                      <stop offset="95%" stopColor={getMetricColor(activeMetric)} stopOpacity={0}/>
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" stroke="hsl(222, 20%, 20%)" />
                  <XAxis 
                    dataKey="time" 
                    stroke="hsl(215, 20%, 65%)"
                    fontSize={12}
                  />
                  <YAxis 
                    stroke="hsl(215, 20%, 65%)"
                    fontSize={12}
                  />
                  <Tooltip 
                    contentStyle={{
                      backgroundColor: "hsl(222, 20%, 11%)",
                      border: "1px solid hsl(222, 20%, 20%)",
                      borderRadius: "8px",
                      color: "hsl(210, 40%, 98%)"
                    }}
                  />
                  <Area
                    type="monotone"
                    dataKey={activeMetric}
                    stroke={getMetricColor(activeMetric)}
                    strokeWidth={3}
                    fillOpacity={1}
                    fill="url(#areaGradient)"
                  />
                </AreaChart>
              </ResponsiveContainer>
            ) : (
              <div className="flex items-center justify-center h-full text-muted-foreground">
                <div className="text-center">
                  <TrendingUp className="w-12 h-12 mx-auto mb-4 opacity-50" />
                  <p>No health data available</p>
                  <p className="text-sm">Connect ESP32 devices to see real-time data</p>
                </div>
              </div>
            )}
          </div>

          {/* Chart Statistics */}
          {chartData.length > 0 && (
            <div className="grid grid-cols-4 gap-4 mt-6 pt-6 border-t border-border">
              <div className="text-center">
                <div className="text-2xl font-bold text-foreground" data-testid="text-current-value">
                  {currentValue}
                </div>
                <div className="text-sm text-muted-foreground">
                  Current {getMetricLabel(activeMetric)}
                </div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-accent" data-testid="text-average-value">
                  {avgValue}
                </div>
                <div className="text-sm text-muted-foreground">
                  Average {getMetricLabel(activeMetric)}
                </div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-destructive" data-testid="text-peak-value">
                  {maxValue}
                </div>
                <div className="text-sm text-muted-foreground">
                  Peak {getMetricLabel(activeMetric)}
                </div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-blue-400" data-testid="text-min-value">
                  {minValue}
                </div>
                <div className="text-sm text-muted-foreground">
                  Min {getMetricLabel(activeMetric)}
                </div>
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

client/src/components/health-data-panel..content:
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent } from "@/components/ui/card";
import { Heart, Activity, TrendingUp, Cpu, Lock, Battery, Signal } from "lucide-react";
import type { Device, HealthMetrics } from "@shared/schema";

export default function HealthDataPanel() {
  const { data: devices = [] } = useQuery<Device[]>({
    queryKey: ["/api/devices"],
    refetchInterval: 5000,
  });

  const { data: healthMetrics = [] } = useQuery<HealthMetrics[]>({
    queryKey: ["/api/health-metrics"],
    refetchInterval: 2000,
  });

  // Get the latest metrics for each device
  const getLatestMetric = (deviceId: string, field: keyof HealthMetrics) => {
    const deviceMetrics = healthMetrics.filter(m => m.deviceId === deviceId);
    if (deviceMetrics.length === 0) return null;
    const latest = deviceMetrics[deviceMetrics.length - 1];
    return latest[field];
  };

  const formatTimeAgo = (date: Date) => {
    const seconds = Math.floor((new Date().getTime() - new Date(date).getTime()) / 1000);
    if (seconds < 60) return `${seconds}s ago`;
    const minutes = Math.floor(seconds / 60);
    if (minutes < 60) return `${minutes}m ago`;
    return `${Math.floor(minutes / 60)}h ago`;
  };

  const formatUptime = (seconds: number) => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    return `${hours}h ${minutes}m`;
  };

  const getSignalBars = (strength: number) => {
    const bars = [];
    const level = Math.abs(strength);
    for (let i = 0; i < 4; i++) {
      const isActive = level < 50 + (i * 15); // -50 to -95 dBm range
      bars.push(
        <div
          key={i}
          className={`w-1 ${isActive ? 'bg-accent' : 'bg-muted/40'} rounded-sm`}
          style={{ height: `${8 + i * 4}px` }}
        />
      );
    }
    return bars;
  };

  // Calculate aggregate metrics
  const aggregateHeartRate = healthMetrics.length > 0 
    ? healthMetrics[healthMetrics.length - 1]?.heartRate || 0 
    : 0;
  const aggregateSpO2 = healthMetrics.length > 0 
    ? healthMetrics[healthMetrics.length - 1]?.spO2 || 0 
    : 0;
  const aggregateIR = healthMetrics.reduce((sum, m) => sum + (m.stepCount || 0), 0);

  const onlineDevice = devices.find(d => d.status === "online");

  return (
    <section>
      <h2 className="text-xl font-semibold mb-6 flex items-center">
        <Heart className="w-5 h-5 text-primary mr-3" />
        Real-Time Health Metrics
      </h2>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {/* Heart Rate Card */}
        <Card className="glass-card cyber-glow" data-testid="card-heart-rate">
          <CardContent className="pt-6">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center space-x-2">
                <Heart className="w-5 h-5 text-red-400" />
                <span className="text-sm font-medium text-muted-foreground">Heart Rate</span>
              </div>
              <div className="px-2 py-1 bg-accent/20 text-accent text-xs rounded-full">
                <Lock className="w-3 h-3 mr-1 inline" />
                Encrypted
              </div>
            </div>

            <div className="space-y-2">
              <div className="text-3xl font-bold text-foreground" data-testid="text-heart-rate">
                {aggregateHeartRate}
              </div>
              <div className="text-sm text-muted-foreground">BPM</div>
              <div className="flex justify-between text-xs text-muted-foreground">
                <span>Min: <span className="text-accent">72</span></span>
                <span>Max: <span className="text-red-400">95</span></span>
              </div>
              <div className="text-xs text-muted-foreground" data-testid="text-heart-rate-timestamp">
                Updated: {healthMetrics.length > 0 && healthMetrics[healthMetrics.length - 1].timestamp ? formatTimeAgo(healthMetrics[healthMetrics.length - 1].timestamp!) : 'Never'}
              </div>
            </div>

            {/* Mini sparkline placeholder */}
            <div className="mt-4 h-8 bg-muted/20 rounded flex items-end space-x-1">
              {[4, 6, 3, 5, 7, 8].map((height, i) => (
                <div
                  key={i}
                  className={`w-1 rounded-t-sm ${i === 5 ? 'bg-primary' : 'bg-primary/60'}`}
                  style={{ height: `${height * 4}px` }}
                />
              ))}
            </div>
          </CardContent>
        </Card>

        {/* SpO2 Card */}
        <Card className="glass-card" data-testid="card-spo2">
          <CardContent className="pt-6">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center space-x-2">
                <Activity className="w-5 h-5 text-blue-400" />
                <span className="text-sm font-medium text-muted-foreground">Blood Oxygen</span>
              </div>
              <div className="px-2 py-1 bg-accent/20 text-accent text-xs rounded-full">
                <Lock className="w-3 h-3 mr-1 inline" />
